const headerBag = Object.fromEntries(Object.entries($json.headers ?? {}).map(([key, value]) => [String(key).toLowerCase(), value]));
const rawBody = $json.bodyRaw ?? $json.rawBody ?? JSON.stringify($json.body ?? $json);
return [{
  json: {
    headers: headerBag,
    rawBody,
    receivedAtUtc: new Date().toISOString(),
    contractVersion: "phase-4-v1"
  }
}];

const crypto = require("crypto");
const appSecret = $env.N8N_TEST_META_APP_SECRET ?? "";
const signatureHeader = String($json.headers["x-hub-signature-256"] ?? "");
const signature = signatureHeader.startsWith("sha256=") ? signatureHeader.slice(7) : "";
const expected = crypto.createHmac("sha256", appSecret).update($json.rawBody, "utf8").digest("hex");
const isSha256Hex = /^[a-f0-9]{64}$/i.test(signature);
const valid = Boolean(appSecret) && isSha256Hex && crypto.timingSafeEqual(Buffer.from(expected, "hex"), Buffer.from(signature, "hex"));
return [{
  json: {
    ...$json,
    metaSignatureValid: valid,
    signatureAlgorithm: "sha256",
    invalidReason: valid ? null : "invalid-meta-signature"
  }
}];

if (!$json.metaSignatureValid) {
  return [{ json: { ...$json, shouldStop: true, responseCode: 401, responseBody: "invalid signature" } }];
}
const envelope = JSON.parse($json.rawBody);
const entry = envelope.entry?.[0] ?? {};
const change = entry.changes?.[0] ?? {};
const message = change.value?.messages?.[0] ?? null;
const contact = change.value?.contacts?.[0] ?? null;
const waId = String(contact?.wa_id ?? message?.from ?? "").trim();
const normalized = waId.replace(/\D/g, "");
const correlationId = [message?.id ?? "meta", normalized || "unknown", change.value?.metadata?.phone_number_id ?? "phone"].join(":").slice(0, 64);
return [{
  json: {
    ...$json,
    shouldStop: !message || !normalized,
    responseCode: !message || !normalized ? 200 : 202,
    responseBody: !message || !normalized ? "ignored" : "accepted",
    envelope,
    message,
    verifiedSender: {
      waId,
      normalized,
      displayName: contact?.profile?.name ?? null
    },
    conversation: {
      eventId: message?.id ?? correlationId,
      eventTimestamp: Number(message?.timestamp ?? 0),
      phoneNumberId: change.value?.metadata?.phone_number_id ?? "",
      correlationId
    },
    inboundText: message?.text?.body ?? "",
    inboundType: message?.type ?? "unsupported"
  }
}];

const original = $("Parse Meta Envelope").first().json;
const commandStdout = String($json.stdout ?? "{}").trim();
const gate = JSON.parse(commandStdout || "{}");
const duplicate = Boolean(gate.duplicate);
const outOfOrder = Boolean(gate.outOfOrder);
return [{
  json: {
    ...original,
    duplicate,
    outOfOrder,
    shouldStop: duplicate || outOfOrder,
    responseCode: 200,
    responseBody: "EVENT_RECEIVED"
  }
}];

const raw = $json.output?.[0]?.content?.[0]?.text ?? $json.body?.output?.[0]?.content?.[0]?.text ?? $json.response?.output_text ?? $json.output_text ?? $json.text ?? "{}";
const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
const allowed = new Set(["availability", "create", "list", "detail", "update", "cancel", "occasionCatalog", "handoff", "unsupported"]);
if (!allowed.has(parsed.intent)) {
  throw new Error("schema-reject: intent no permitido");
}
return [{
  json: {
    ...$json,
    llmResult: parsed,
    shouldStop: false
  }
}];

const crypto = require("crypto");
const activeKid = $env.N8N_TEST_WHATSAPP_ASSERTION_ACTIVE_KID;
const issuer = $env.N8N_TEST_WHATSAPP_ASSERTION_ISSUER;
const audience = $env.N8N_TEST_WHATSAPP_ASSERTION_AUDIENCE;
const signingKey = $env.N8N_TEST_WHATSAPP_ASSERTION_ACTIVE_KEY;
if (!activeKid || !issuer || !audience || !signingKey) {
  throw new Error("missing-required-whatsapp-assertion-configuration");
}
const header = Buffer.from(JSON.stringify({ alg: "HS256", typ: "JWT", kid: activeKid })).toString("base64url");
const now = Math.floor(Date.now() / 1000);
const action = $json.botRequest?.operation === "availability" || $json.botRequest?.operation === "list" || $json.botRequest?.operation === "detail" || $json.botRequest?.operation === "occasionCatalog"
  ? "reservations.read"
  : "reservations.mutate";
const payload = {
  iss: issuer,
  aud: audience,
  sub: $json.verifiedSender.waId,
  jti: crypto.randomUUID(),
  scope: "openresto.whatsapp reservations",
  'openresto:channel_action': action,
  iat: now,
  exp: now + 120
};
const encodedPayload = Buffer.from(JSON.stringify(payload)).toString("base64url");
const signingInput = header + "." + encodedPayload;
const signature = crypto.createHmac("sha256", signingKey).update(signingInput).digest("base64url");
return [{ json: { ...$json, issuedAssertion: signingInput + "." + signature, assertionKid: activeKid } }];
